SELECT p.hadm_id, (percentile_cont(0.75) within GROUP (ORDER BY p.value) - percentile_cont(0.25) within GROUP (ORDER BY p.value)) AS interquartile_range FROM patients p JOIN procedureevents e ON p.subject_id = e.subject_id WHERE p.gender = 'F' AND p.anchor_year = 91 AND EXTRACT(YEAR FROM p.dob) BETWEEN 86 AND 96 AND e.procedure_code = 'MCS' GROUP BY p.hadm_id ORDER BY interquartile_range NULLS LAST;